fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();

    // First output matrix: each row is a clone of x
    let x_matrix: Vec<Vec<f32>> = (0..rows)
        .map(|_| x.clone())
        .collect();

    // Second output matrix: each row is y[i] repeated cols times
    let y_matrix: Vec<Vec<f32>> = y.into_iter()
        .map(|val| vec![val; cols])
        .collect();

    (x_matrix, y_matrix)
}